#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "spglib.h"
#include "cell.h"
#include "symmetry.h"
#include "spin.h"

int main() {
    // Structure from PR description
    double lattice[3][3] = {
        {3.36017962, 0.0, 0.95244787},
        {1.70747655, 3.84457132, 0.37960516},
        {-0.0117898, -0.29501452, 6.4450749},
    };
    double positions[][3] = {
        {0.0, 0.0, 0.0},
        {0.26737473, 0.2232512, 0.24199933},
        {0.73262527, 0.7767488, 0.75800067},
    };
    int numbers[] = {0, 1, 1};
    double magmoms[] = {0.005, 0.002, 0.002};
    int num_atom = 3;
    int tensor_rank = 0; // COLLINEAR
    double symprec = 1e-2;
    double angle_tolerance = -1.0;
    double mag_symprec = symprec;

    // Step 1: Create cell
    fprintf(stderr, "DEBUG: Creating cell\n"); fflush(stderr);
    Cell *cell = cel_alloc_cell(num_atom, tensor_rank);
    if (cell == NULL) {
        fprintf(stderr, "DEBUG: cel_alloc_cell failed\n"); fflush(stderr);
        return 1;
    }
    cel_set_cell_with_tensors(cell, lattice, positions, numbers, magmoms);
    fprintf(stderr, "DEBUG: Cell created\n"); fflush(stderr);

    // Step 2: Get dataset (non-spin symmetry)
    fprintf(stderr, "DEBUG: Getting dataset\n"); fflush(stderr);
    SpglibDataset *dataset = spg_get_dataset(lattice, positions, numbers, num_atom, 0, symprec);
    if (dataset == NULL) {
        fprintf(stderr, "DEBUG: spg_get_dataset returned NULL\n"); fflush(stderr);
        return 1;
    }
    fprintf(stderr, "DEBUG: Dataset has %d operations\n", dataset->n_operations); fflush(stderr);

    // Step 3: Create Symmetry from dataset
    fprintf(stderr, "DEBUG: Creating Symmetry\n"); fflush(stderr);
    Symmetry *sym_nonspin = sym_alloc_symmetry(dataset->n_operations);
    if (sym_nonspin == NULL) {
        fprintf(stderr, "DEBUG: sym_alloc_symmetry failed\n"); fflush(stderr);
        return 1;
    }
    for (int i = 0; i < dataset->n_operations; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                sym_nonspin->rot[i][j][k] = dataset->rotations[i][j][k];
            }
        }
        for (int j = 0; j < 3; j++) {
            sym_nonspin->trans[i][j] = dataset->translations[i][j];
        }
    }
    sym_nonspin->size = dataset->n_operations;
    spg_free_dataset(dataset);
    fprintf(stderr, "DEBUG: Symmetry created with %d operations\n", sym_nonspin->size); fflush(stderr);

    // Step 4: Call spn_get_operations_with_site_tensors
    fprintf(stderr, "DEBUG: Calling spn_get_operations_with_site_tensors\n"); fflush(stderr);
    int *equiv_atoms = NULL;
    int *permutations = NULL;
    double prim_lattice[3][3];

    MagneticSymmetry *mag_sym = spn_get_operations_with_site_tensors(
        &equiv_atoms, &permutations, prim_lattice, sym_nonspin, cell,
        1 /* with_time_reversal */, 0 /* is_axial */, symprec, angle_tolerance, mag_symprec
    );

    if (mag_sym == NULL) {
        fprintf(stderr, "DEBUG: spn_get_operations_with_site_tensors returned NULL\n"); fflush(stderr);
    } else {
        fprintf(stderr, "DEBUG: Magnetic symmetry has %d operations\n", mag_sym->size); fflush(stderr);
    }

    return 0;
}
